import { lagosDayStart } from "@/lib/vendor-calendar";
import { prisma } from "@/lib/db";
import { Panel } from "@/components/admin/panel";
export async function StaffTimeline({ vendorId }: {
    vendorId: string;
}) {
    const start = lagosDayStart(), end = new Date(start.getTime() + 86400000), weekday = new Date(start.getTime() + 3600000).getUTCDay();
    const [staff, allSlots, bookings] = await Promise.all([prisma.vendorStaff.findMany({ where: { vendorId, active: true }, select: { id: true, name: true }, orderBy: { name: 'asc' } }), prisma.availabilitySlot.findMany({ where: { vendorId } }), prisma.booking.findMany({ where: { vendorId, startsAt: { gte: start, lt: end }, status: { in: ['confirmed', 'in_progress', 'pending', 'awaiting_payment'] } }, select: { id: true, staffId: true, startsAt: true, endsAt: true, locationType: true, service: { select: { name: true } } } })]);
    return <Panel title={`Today · ${start.toLocaleDateString('en-NG', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'Africa/Lagos' })}`} description="Therapist shifts and appointments · WAT" bodyClassName="p-0" className="mb-5"><div className="overflow-x-auto"><div className="min-w-[850px]"><div className="ml-44 grid grid-cols-13 border-b border-line py-3 text-[10px] text-ink2" style={{ gridTemplateColumns: 'repeat(13,minmax(0,1fr))' }}>{Array.from({ length: 13 }, (_, i) => <span key={i}>{i + 9}:00</span>)}</div>{staff.length ? staff.map(s => { const own = allSlots.filter(sl => sl.staffId === s.id), applicable = (own.length ? own : allSlots.filter(sl => !sl.staffId)).filter(sl => sl.weekday === weekday); const events = bookings.filter(b => b.staffId === s.id); return <div key={s.id} className="flex items-center border-b border-line last:border-b-0"><div className="w-44 shrink-0 p-4"><p className="text-xs font-semibold">{s.name}</p><p className="mt-1 text-[10px] text-ink2">{applicable.length ? applicable.map(sl => `${Math.floor(sl.startMin / 60)}:${String(sl.startMin % 60).padStart(2, '0')} – ${Math.floor(sl.endMin / 60)}:${String(sl.endMin % 60).padStart(2, '0')}`).join(', ') : 'Off today'}</p></div><div className="relative h-20 flex-1">{applicable.map(sl => <div key={sl.id} className="absolute inset-y-3 rounded bg-elev" style={{ left: `${Math.max(0, (sl.startMin - 540) / 780 * 100)}%`, width: `${Math.max(0, (Math.min(1320, sl.endMin) - Math.max(540, sl.startMin)) / 780 * 100)}%` }}/>)}{events.map(b => { const a = new Date(b.startsAt.getTime() + 3600000), min = a.getUTCHours() * 60 + a.getUTCMinutes(); return <a key={b.id} href={'/vendor/bookings?q=' + encodeURIComponent(b.service.name)} title={`${b.service.name} · ${b.locationType}`} className="absolute inset-y-5 overflow-hidden rounded border-l-2 border-gold bg-gold/20 px-2 py-1 text-[10px]" style={{ left: `${Math.max(0, (min - 540) / 780 * 100)}%`, width: `${Math.max(2, Math.min(1320 - min, (b.endsAt.getTime() - b.startsAt.getTime()) / 60000) / 780 * 100)}%` }}>{b.service.name}</a>; })}</div></div>; }) : <p className="p-8 text-sm text-ink2">Add a therapist to build your schedule.</p>}</div></div></Panel>;
}
